/**
 * The read-only rule for workspaces whose subscription is not in good standing.
 *
 * Pure: takes the stored subscription and a clock, and answers whether writes are locked and why.
 * The service layer enforces the answer via `assertWorkspaceWritable`.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Thrown by every guarded write while the workspace is locked. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace ${orgId} is read-only (${reason})`);
    this.name = "WorkspaceLockedError";
  }
}

/** `null` when writable. A cancellation scheduled for later keeps the lock off until its date. */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (!subscription) return null;

  if (subscription.status === "past_due") return "past_due";

  if (subscription.status === "trialing") {
    return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
  }

  if (subscription.status === "canceled") {
    if (subscription.cancelAt === null) return "canceled";
    return reached(subscription.cancelAt, now) ? "canceled" : null;
  }

  return null;
}

function reached(at: string, now: Date): boolean {
  return new Date(at).getTime() <= now.getTime();
}
EOF
